267	    fn is_path_ignored(&self, params: IsPathIgnoredParams) -> Result<bool, WorkspaceError> {
268	        let settings = self.settings();
269	        let path = params.rome_path.as_path();
270	        if path.file_name().and_then(|s| s.to_str()) == Some(BIOME_JSON) {
271	            return Ok(false);
272	        }
273	
274	        // Overrides have top priority
275	        let excluded_by_override = settings.as_ref().override_settings.is_path_excluded(path);
276	        if excluded_by_override.unwrap_or_default() {
277	            return Ok(true);
278	        }
279	        let included_by_override = settings.as_ref().override_settings.is_path_included(path);
280	        if included_by_override.unwrap_or_default() {
281	            return Ok(false);
282	        }
283	
284	        let (ignored_files, included_files) = match params.feature {
285	            FeatureName::Format => {
286	                let formatter = &settings.as_ref().formatter;
287	                (&formatter.ignored_files, &formatter.included_files)
288	            }
289	            FeatureName::Lint => {
290	                let linter = &settings.as_ref().linter;
291	                (&linter.ignored_files, &linter.included_files)
292	            }
293	            FeatureName::OrganizeImports => {
294	                let organize_imports = &settings.as_ref().organize_imports;
295	                (
296	                    &organize_imports.ignored_files,
297	                    &organize_imports.included_files,
298	                )
299	            }
300	        };
301	
302	        // Tool include/ignore have priority over (global) files include/ignore
303	        if ignored_files.matches_path(path) {
304	            return Ok(true);
305	        }
306	        if !included_files.is_empty() && included_files.matches_path(path) {
307	            return Ok(false);
308	        }
309	
310	        Ok(self.is_ignored_by_top_level_config(path))
311	    }
