151	                // - `out/` -> matches
152	                // - `layout.tsx` -> does not match
153	                // - `routes/foo.ts` -> does not match
154	                source
155	                    .ancestors()
156	                    .any(|ancestor| ancestor.ends_with(pattern.as_str()))
